create table if not exists users(id serial primary key,name text not null,email text unique not null,phone text,role text not null,salt text not null,password_hash text not null,created_at timestamptz default now());
create table if not exists stations(id serial primary key,owner_email text not null references users(email),name text not null,address text not null,ports int not null,connector text not null,price numeric not null,status text not null,lat double precision,lng double precision);
create table if not exists bookings(id serial primary key,station_id int not null references stations(id),customer_email text not null references users(email),date_text text not null,slot text not null,energy numeric not null,amount numeric not null,status text not null,payment text not null,unique(station_id,date_text,slot,customer_email));
